import{_ as a,b as e,f as r,I as d}from"./chunks/framework.DYvp_Vyw.js";const B=JSON.parse('{"title":"《大数据原理》- 第一章 - 第一节","description":"","frontmatter":{"title":"《大数据原理》- 第一章 - 第一节","date":"2025-05-10T01:01:13.000Z","tags":["大数据原理","Hadoop"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Hadoop-Class-Study-001.md","filePath":"posts/Hadoop-Class-Study-001.md"}'),l={name:"posts/Hadoop-Class-Study-001.md"};function o(s,t,n,i,h,p){return r(),e("div",null,t[0]||(t[0]=[d('<p>根据学校的PPT自己学习后整理的笔记（实时更新）</p><hr><h1 id="_1-大数据概念" tabindex="-1">1.大数据概念 <a class="header-anchor" href="#_1-大数据概念" aria-label="Permalink to &quot;1.大数据概念&quot;">​</a></h1><ul><li>大数据（Big Data）：指<span style="color:red;">无法在一定时间范围</span>内用常规软件工具进行捕捉、管理和处理的数据集合，是需要新处理模式才能具有更强的决策力、洞察发现力和流程优化能力的<span style="color:red;">海量、高增长率和多样化</span>的<span style="color:red;">信息资产</span>。 大数据主要解决，<span style="color:red;">海量</span>数据的<span style="color:red;">采集、存储</span>和<span style="color:red;">分析计算</span>问题。</li></ul><h2 id="数据存储单位换算表" tabindex="-1">数据存储单位换算表 <a class="header-anchor" href="#数据存储单位换算表" aria-label="Permalink to &quot;数据存储单位换算表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单位名称</th><th>换算关系</th></tr></thead><tbody><tr><td>bit</td><td>最小单位（二进制位）</td></tr><tr><td>Byte</td><td>1 Byte = 8 bit</td></tr><tr><td>KB</td><td>1 KB = 1024 Byte</td></tr><tr><td>MB</td><td>1 MB = 1024 KB</td></tr><tr><td>GB</td><td>1 GB = 1024 MB</td></tr><tr><td>TB</td><td>1 TB = 1024 GB</td></tr><tr><td>PB</td><td>1 PB = 1024 TB</td></tr><tr><td>EB</td><td>1 EB = 1024 PB</td></tr><tr><td>ZB</td><td>1 ZB = 1024 EB</td></tr><tr><td>YB</td><td>1 YB = 1024 ZB</td></tr><tr><td>BB</td><td>1 BB = 1024 YB</td></tr><tr><td>NB</td><td>1 NB = 1024 BB</td></tr><tr><td>DB</td><td>1 DB = 1024 NB</td></tr></tbody></table><h1 id="_2-大数据特点" tabindex="-1">2.大数据特点 <a class="header-anchor" href="#_2-大数据特点" aria-label="Permalink to &quot;2.大数据特点&quot;">​</a></h1><h2 id="_1、volume-大量" tabindex="-1">1、Volume（大量） <a class="header-anchor" href="#_1、volume-大量" aria-label="Permalink to &quot;1、Volume（大量）&quot;">​</a></h2><p>截至目前，人类生产的所有<span style="color:red;">印刷材料的数据量是200PB</span>，而历史上全人类总共<span style="color:red;">说过的话的数据量大约是5EB</span>。当前，典型个人计算机硬盘的容量为TB量级，而一些大<span style="color:red;">企业的数据量已经接近EB</span>量级。</p><h2 id="_2、velocity-高速" tabindex="-1">2、Velocity（高速） <a class="header-anchor" href="#_2、velocity-高速" aria-label="Permalink to &quot;2、Velocity（高速）&quot;">​</a></h2><p>这是大数据区分于传统数据挖掘的最显著特征。根据IDC的“数字宇宙”的报告，预计到2025年，全球数据使用量将达到163ZB。在如此海量的数据面前，处理数据的效率就是企业的生命。</p><h2 id="_3、variety-多样" tabindex="-1">3、Variety（多样） <a class="header-anchor" href="#_3、variety-多样" aria-label="Permalink to &quot;3、Variety（多样）&quot;">​</a></h2><p>这种类型的多样性也让数据被分为结构化数据和非结构化数据。相对于以往便于存储的<span style="color:red;">以数据库/文本为主的结构化数据</span>，<span style="color:red;">非结构化数据</span>越来越多，包括<span style="color:red;">网络日志、音频、视频、图片、地理位置信息</span>等，这些多类型的数据对数据的处理能力提出了更高要求。</p><h2 id="_4、value-低价值密度" tabindex="-1">4、Value（低价值密度） <a class="header-anchor" href="#_4、value-低价值密度" aria-label="Permalink to &quot;4、Value（低价值密度）&quot;">​</a></h2><p>价值密度的高低与数据总量的大小成反比。 比如，在一天监控视频中，我们只关心宋宋老师晚上在床上健身那一分钟，<span style="color:red;">如何快速对有价值数据“提纯”成为目前大数据背景下待解决的难题</span>。</p><h1 id="_3-大数据应用场景" tabindex="-1">3.大数据应用场景 <a class="header-anchor" href="#_3-大数据应用场景" aria-label="Permalink to &quot;3.大数据应用场景&quot;">​</a></h1><ul><li>1、抖音：推荐的都是你喜欢的视频</li><li>2、零售：分析用户消费习惯，为用户购买商品提供方便，从而提升商品销量。经典案例，纸尿布+啤酒。</li><li>3、房产：大数据全面助力房地产行业，打造精准投策与营销，选出更合适的地，建造更合适的楼，卖给更合适的人。</li><li>4、保险：海量数据挖掘及风险预测，助力保险行业精准营销，提升精细化定价能力。</li></ul><h1 id="_4-大数据发展前景" tabindex="-1">4.大数据发展前景 <a class="header-anchor" href="#_4-大数据发展前景" aria-label="Permalink to &quot;4.大数据发展前景&quot;">​</a></h1><p>1、党的十九大提出“推动互联网、大数据、人工智能和实体经济深度融合”。 2、2020年初，中央推出34万亿“新基建”投资计划 3、当前大数据发展前景非常广阔，技术不断进步，应用领域日益广泛，市场规模持续增长。大数据在医疗、金融、制造、智慧城市等行业的应用不断深化，推动了各行各业的创新和效率提升。尽管面临数据安全和人才短缺等挑战，但随着技术的成熟和政策的支持，大数据的未来充满机遇。</p><hr>',20)]))}const u=a(l,[["render",o]]);export{B as __pageData,u as default};
